import sys

def can_solve(n, k):
    if n < k:
        return False
    if n == k:
        return True
    if k == 1:
        return n == 1
    if k == 2:
        return n >= 3
    if k == 3:
        return n >= 6
    if k == 4:
        return n >= 10
    if k == 5:
        return n >= 15
    if k == 6:
        return n >= 21
    if k == 7:
        return n >= 28
    if k == 8:
        return n >= 36
    if k == 9:
        return n >= 45
    if k == 10:
        return n >= 55
    # General case for k > 10
    return n >= k * (k + 1) // 2

def find_distribution(n, k):
    if not can_solve(n, k):
        return "NO"

    # Start with the minimum sequence that satisfies the conditions
    a = [1] * k
    remaining = n - k

    # Distribute the remaining problems
    i = 0
    while remaining > 0:
        a[i] += 1
        remaining -= 1
        if i < k - 1 and a[i] * 2 <= a[i + 1]:
            i += 1

    return "YES", a

