def can_train(n, k):
    # Check if it's possible to distribute n problems over k days
    if n < k:
        return False
    if n > (1 << k) - 1:
        return False
    return True

def generate_training_plan(n, k):
    if not can_train(n, k):
        return "NO"

    plan = []
    current_problems = 1
    remaining_problems = n

    for i in range(k):
        if remaining_problems <= 0:
            break
        max_possible = min(remaining_problems, 2 * current_problems)
        plan.append(current_problems)
        remaining_problems -= current_problems
        current_problems = min(max_possible, remaining_problems + 1)

    if remaining_problems != 0:
        return "NO"

    return "YES", plan

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    result = generate_training_plan(n, k)

    if result == "NO":
